LEVEL_IDENTITIES={618: ('NUI_CHICKEN', 'chicken.lua'), 201: ('NUI_THIEF_THIN_ZERO', 'thief_thin_zero.lua'), 632: ('NUI_CHICKEN_FEMALE', 'chicken_female.lua'), 5: ('NUI_BENDERS_NORMAL', 'benders_normal.lua')}

def _fingerprint(value):
    return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(',',':'),allow_nan=False).encode()).hexdigest()

def _f32(value):return struct.unpack('<f',struct.pack('<f',value))[0]

def _hp(base,growth,level):
    return _f32(_f32(_f32(base)+_f32(_f32(growth)*_f32(level)))*_f32(1))

def _definition(template,identity):
    from els_server.game_data import client_data
    try:n=client_data().npc(template)
    except ValueError:return False
    return (n['enum']=='NPC_UNIT_ID.'+identity[0] and (n['script'] or '').lower()==identity[1]
            and n['class_id']==0 and n['is_npc'] is True)

def _solo(session):
    app=getattr(session,'application',None) or getattr(session,'_c1_local_application',None)
    if app is None:return False
    world=app.world
    return (not world.party_of.get(session) and world.dungeons.room(session) is None
            and not getattr(session,'solo_challenge_party',None))

def _lease(session):
    """Actual Application ownership only; standalone fixture sessions get no C1."""
    from pathlib import Path
    from els_server.application import Application,FriendsSession
    from els_server.domain.local_session import LocalSession,LocalAccount
    from els_server.storage.local_state import LocalState
    account=getattr(session,'account',None);root=getattr(account,'root',None)
    if (type(account) is not LocalAccount or type(account.store) is not LocalState
        or account.store.uid!=account.uid or root is None or root.root is not root
        or root.character_accounts.get(account.uid) is not account):return False
    app=getattr(session,'application',None)
    if app is not None:
        from els_server.domain.dungeon_equipment_loot_flow import current_lease
        return (type(session) is FriendsSession and type(app) is Application
                and app.config.mode=='friends' and current_lease(session)
                and app.registry.enabled(session.identity['id'])
                and Path(app.config.state_file).resolve()==Path(account.store.path).resolve())
    app=getattr(session,'_c1_local_application',None)
    return (type(session) is LocalSession and type(app) is Application and app.config.mode=='local'
            and getattr(session,'_c1_local_live',False) is True and type(root) is LocalAccount
            and app.account is root and account.account_id==root.account_id
            and Path(app.config.state_file).resolve()==Path(account.store.path).resolve())

def prepare(session,event,dungeon,run_id,challenge):
    """Only an already admitted, party-free native entrance creates a capability."""
    if (dungeon not in MAPS or challenge is not None or session.role!='game'
        or session.client_build!='dx11_260923' or session.phase!='town_ready'
        or not session.dungeon_requested or session.requested_dungeon_id!=dungeon
        or event.kind not in (0x37f,0x382) or session.requested_dungeon_mode!=(2 if event.kind==0x37f else 1)
        or event.event_id!=0x202 or event.performers not in ((),(0,)) or event.uid!=2**64-1 or event.target_uid!=2**64-1
        or event.payload_mode!=0 or not _lease(session) or not _solo(session)):
        return None
    return _Context(session,dungeon,str(uuid.UUID(run_id)))

class _Context:
    def __init__(self,session,dungeon,run_id):
        self.session=session;self.account=session.account;self.store=session.account.store
        self.uid=session.account.uid;self.account_id=session.account.account_id
        self.admission_mode=session.requested_dungeon_mode
        self.dungeon=dungeon;self.run_id=run_id;self.run=None;self.preparing=True

    def _valid_lease(self):
        s=self.session
        return (s.account is self.account and s.account.store is self.store and self.store is not None
                and s.account.uid==self.uid and s.account.account_id==self.account_id
                and _lease(s) and _solo(s))

    def _refuse(self):
        from els_server.domain.local_session import SessionOrderError
        raise SessionOrderError('C1 HP instance lease/phase changed')

    def bind_run(self,run):
        if (not self.preparing or self.run is not None or not self._valid_lease()
            or run.identity!=self.dungeon or run.run_id!=self.run_id):self._refuse()
        self.run=run

    def activate(self,run):
        if run is not self.run or not self._valid_lease():self._refuse()
        self.preparing=False
        if getattr(self.session,'application',None) is None:
            self.session._c1_local_application._c1_local_context=self

    def check(self,run=None,*,emitting=False):
        s=self.session
        if not self._valid_lease() or run is not self.run:self._refuse()
        if run is not None and (run.identity!=self.dungeon or run.run_id!=self.run_id):self._refuse()
        if emitting and run is not None and run.graph['source_sha256']!=MAPS[self.dungeon][0]:self._refuse()
        if self.preparing:
            if (emitting or s.phase!='town_ready' or not s.dungeon_requested
                or s.requested_dungeon_id!=self.dungeon or s.requested_dungeon_mode!=self.admission_mode):self._refuse()
        elif (getattr(s,'_c1_hp_context',None) is not self or s.dungeon_run is not run
              or s.dungeon_id!=self.dungeon or s.phase not in ('dungeon_loading','dungeon_active')
              or s.dungeon_participants!=frozenset((self.uid,)) or s.clear_notified or s.dungeon_failed
              or getattr(s,'active_challenge',None) is not None or getattr(s,'challenge_deadline',None) is not None
              or (s.reward_test and s.reward_run_id!=self.run_id)):
            self._refuse()
        if (not self.preparing and getattr(s,'application',None) is None
            and getattr(s._c1_local_application,'_c1_local_context',None) is not self):self._refuse()

    def source_hp(self,run,stage,part,group,source,fallback):
        self.check(run)
        if run.graph['source_sha256']!=MAPS[self.dungeon][0]:return fallback
        template=source['template'];identity=IDENTITIES.get(template)
        if identity is None or not _definition(template,identity):return fallback
        # Modern explicit source HP always wins over this finite local policy.
        if run.catalog._data['npcs'][str(template)]['script_max_hp'] is not None:return fallback
        if source.get('ally') or source.get('team',1)!=1 or source.get('dynamic'):return fallback
        key=(self.dungeon,stage,part,group,source['source_index'],template,_fingerprint(source))
        if key not in SOURCES:return fallback
        level=run.catalog.static_npc_level(self.dungeon,run.graph,stage,part,source)
        if level!=MAPS[self.dungeon][1]:return fallback
        return _hp(identity[2],identity[3],level)

    def legacy_population(self,stage,npcs):
        self.check(None,emitting=True)
        if self.dungeon!=30000:return npcs
        from els_server.domain.dungeon_routes import route_catalog
        from els_server.domain.dungeon_npcs import resource_dto,encode_npc
        catalog=route_catalog();graph=catalog.graph(30000)
        if graph['source_sha256']!=MAPS[30000][0]:return npcs
        result=[]
        for original in npcs:
            row=dict(original);result.append(row)
            witness=LEGACY_SOURCES.get((stage,row['key']))
            if witness is None or witness[1]!=row['template'] or witness[2]!=_fingerprint(original):continue
            group=graph['stages'][str(stage)]['parts']['0']['groups']
            if len(group)!=1 or group[0]['index']!=-1:continue
            source=next((x for x in group[0]['npcs'] if x['source_index']==witness[0]),None)
            if source is None or _fingerprint(source)!=witness[3]:continue
            template=row['template'];identity=LEVEL_IDENTITIES.get(template)
            if identity is None or not _definition(template,identity):continue
            if source.get('ally') or source.get('team',1)!=1:continue
            level=catalog.static_npc_level(30000,graph,stage,0,source)
            if level!=2:continue
            raw=bytearray.fromhex(row['resource_hex'])
            if len(raw)!=0x98 or struct.unpack_from('<ii',raw)!=(row['key'],template):continue
            # Only these four same-source basic NPC identities receive level2;
            # gates, world blocks and boxes retain their existing bytes.
            raw[0x0c]=level
            row['resource_hex']=raw.hex();row['wire_hex']=encode_npc(resource_dto(raw),0).hex()
            native=catalog._data['npcs'][str(template)]
            maximum=native['script_max_hp'];rule=IDENTITIES.get(template)
            if maximum is None and rule is not None:
                occurrence=(30000,stage,0,-1,source['source_index'],template,_fingerprint(source))
                if occurrence in SOURCES:maximum=_hp(rule[2],rule[3],level)
            if maximum is None:continue
            if type(maximum) not in (int,float) or not math.isfinite(maximum) or maximum<=0:continue
            init=bytearray.fromhex(row['init_hex']);cursor=5
            if struct.unpack_from('>i',init)[0]!=template:continue
            for i in range(6):
                if i==4:
                    if init[cursor]!=1:raise ValueError('C1 native init flag')
                    cursor+=1
                length=struct.unpack_from('>I',init,cursor)[0];cursor+=4+length
            if len(init)-cursor!=98:raise ValueError('C1 native97byte stat boundary')
            struct.pack_into('>f',init,cursor+4,maximum)
            row['init_hex']=init.hex();row['hp']=_f32(maximum)
        return result
